  "verdict": "gap",
  "citations": [
    "rbi-13155"
  ],
  "evidence": [
    {
      "doc_id": "rbi-13155",
      "quote": "Card-issuers shall seek One Time Password (OTP) based consent from the cardholder for activating a credit card, if the same has not been activated by the customer for more than 30 days from the date of issuance. If no consent is received for activating the card, card-issuers shall close the credit card account without any cost to the customer within seven working days from date of seeking confirmation from the customer."
    }
  ],
  "confidence": 0.95,
  "rationale": "The clause correctly states the requirement to seek OTP-based consent if the card is not activated within 30 days, but omits the mandatory requirement to close the credit card account without cost within seven working days if no consent is received."
}
